import { Component, Input, Output, EventEmitter, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl' | 'full' | 'bottom';

@Component({
  selector: 'app-modal',
  template: `
    <div 
      *ngIf="isOpen" 
      class="modal-overlay" 
      (click)="onOverlayClick($event)"
      role="dialog" 
      aria-modal="true" 
      [attr.aria-labelledby]="titleId"
      [attr.aria-describedby]="bodyId"
    >
      <div 
        class="modal" 
        [class]="'modal-' + size"
        [class.modal-bottom]="size === 'bottom'"
        (click)="onModalClick($event)"
      >
        <div *ngIf="showHeader" class="modal-header">
          <h2 *ngIf="title" id="{{titleId}}" class="modal-title">{{ title }}</h2>
          <ng-content select="[slot=header]"></ng-content>
          <button 
            *ngIf="closable" 
            class="modal-close" 
            (click)="close()"
            aria-label="Close modal"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <line x1="18" y1="6" x2="6" y2="18"></line>
              <line x1="6" y1="6" x2="18" y2="18"></line>
            </svg>
          </button>
        </div>
        
        <div id="{{bodyId}}" class="modal-body">
          <ng-content></ng-content>
          <ng-template *ngIf="bodyTemplate" [ngTemplateOutlet]="bodyTemplate"></ng-template>
        </div>
        
        <div *ngIf="showFooter" class="modal-footer">
          <ng-content select="[slot=footer]"></ng-content>
          <div *ngIf="!footerTemplate" class="default-actions">
            <button 
              *ngIf="showCancel" 
              class="btn btn-outline-secondary" 
              (click)="close()"
            >
              {{ cancelText }}
            </button>
            <button 
              *ngIf="showConfirm" 
              class="btn" 
              [class]="'btn-' + confirmVariant"
              [disabled]="confirmLoading"
              (click)="confirm()"
            >
              {{ confirmText }}
            </button>
          </div>
        </div>
      </div>
    </div>
  `,
  styles: []
})
export class ModalComponent {
  @Input() isOpen = false;
  @Input() title = '';
  @Input() size: ModalSize = 'md';
  @Input() closable = true;
  @Input() closeOnOverlayClick = true;
  @Input() showHeader = true;
  @Input() showFooter = false;
  @Input() showCancel = true;
  @Input() showConfirm = false;
  @Input() cancelText = 'Cancel';
  @Input() confirmText = 'Confirm';
  @Input() confirmVariant: 'primary' | 'secondary' | 'danger' | 'success' = 'primary';
  @Input() confirmLoading = false;
  @Input() bodyTemplate: TemplateRef<any> | null = null;
  @Input() footerTemplate: TemplateRef<any> | null = null;
  @Input() headerTemplate: TemplateRef<any> | null = null;

  @Output() closed = new EventEmitter<void>();
  @Output() confirmed = new EventEmitter<void>();

  titleId = `modal-title-${Math.random().toString(36).substr(2, 9)}`;
  bodyId = `modal-body-${Math.random().toString(36).substr(2, 9)}`;

  onOverlayClick(event: MouseEvent): void {
    if (this.closeOnOverlayClick && event.target === event.currentTarget) {
      this.close();
    }
  }

  onModalClick(event: MouseEvent): void {
    event.stopPropagation();
  }

  close(): void {
    this.isOpen = false;
    this.closed.emit();
  }

  confirm(): void {
    this.confirmed.emit();
  }
}