export enum UserRole {
  STUDENT = 'student',
  PEER_COUNSELOR = 'peer_counselor',
  GUIDANCE_STAFF = 'guidance_staff',
  ADMIN = 'admin'
}

export enum Campus {
  RUARAKA = 'ruaraka',
  TOWN = 'town',
  KITENGELA = 'kitengela'
}

export interface CampusInfo {
  id: Campus;
  name: string;
  fullName: string;
  location: string;
  address: string;
  phone: string;
  email: string;
  imageUrl: string;
  description: string;
  coordinates?: {
    lat: number;
    lng: number;
  };
}

export interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: UserRole;
  campus: Campus;
  avatarUrl?: string;
  phone?: string;
  studentId?: string;
  staffId?: string;
  isActive: boolean;
  createdAt: Date;
  lastLoginAt?: Date;
}

export interface PeerCounselor extends User {
  role: UserRole.PEER_COUNSELOR;
  trainingStatus: TrainingStatus;
  trainingCompletedAt?: Date;
  supportAreas: SupportArea[];
  availability: AvailabilitySlot[];
  virtualSupportAvailable: boolean;
  supervisorId?: string;
  bio?: string;
  languages: string[];
  rating?: number;
  totalSessions: number;
}

export interface GuidanceStaff extends User {
  role: UserRole.GUIDANCE_STAFF;
  professionalTitle: string;
  specialization: string[];
  licenseNumber: string;
  campus: Campus;
  campusName?: string;
  availability: AvailabilitySlot[];
  virtualSupportAvailable: boolean;
  supervisedCounselors: string[];
  bookingUrl?: string;
  sessionFee: number;
  yearsExperience: number;
}

export interface Student extends User {
  role: UserRole.STUDENT;
  program: string;
  yearOfStudy: number;
  peerCounselorId?: string;
  wellnessJourney?: WellnessJourney;
}

export interface Admin extends User {
  role: UserRole.ADMIN;
  permissions: AdminPermission[];
}

export type AdminPermission = 
  | 'user_management'
  | 'campus_management'
  | 'role_management'
  | 'peer_counselor_management'
  | 'guidance_staff_management'
  | 'wellness_content_management'
  | 'event_management'
  | 'resource_management'
  | 'social_links_management'
  | 'system_settings'
  | 'audit_logs'
  | 'reports';

export enum TrainingStatus {
  NOT_STARTED = 'not_started',
  IN_PROGRESS = 'in_progress',
  COMPLETED = 'completed',
  CERTIFIED = 'certified'
}

export enum SupportArea {
  ACADEMIC_PRESSURE = 'academic_pressure',
  ADJUSTMENT = 'adjustment',
  MOTIVATION = 'motivation',
  FRIENDSHIP_SOCIAL = 'friendship_social',
  RELATIONSHIP = 'relationship',
  GENERAL_WELLBEING = 'general_wellbeing',
  STRESS_MANAGEMENT = 'stress_management',
  ANXIETY_WORRY = 'anxiety_worry',
  SLEEP_WELLBEING = 'sleep_wellbeing',
  FINANCIAL_CHALLENGES = 'financial_challenges',
  CAREER_GUIDANCE = 'career_guidance',
  FAMILY_ISSUES = 'family_issues'
}

export interface AvailabilitySlot {
  dayOfWeek: number;
  startTime: string;
  endTime: string;
  isVirtual: boolean;
  location?: string;
}

export interface WellnessJourney {
  moodCheckins: MoodCheckin[];
  quietSpaceSessions: QuietSpaceSession[];
  resourcesCompleted: ResourceCompletion[];
  challengesCompleted: ChallengeCompletion[];
  supportConversations: number;
  appointmentsAttended: number;
  personalActivities: PersonalActivity[];
}

export interface MoodCheckin {
  id: string;
  mood: MoodLevel;
  note?: string;
  createdAt: Date;
}

export enum MoodLevel {
  GREAT = 'great',
  GOOD = 'good',
  OKAY = 'okay',
  LOW = 'low',
  STRESSED = 'stressed',
  VERY_LOW = 'very_low'
}

export interface QuietSpaceSession {
  id: string;
  type: QuietSpaceType;
  duration: number;
  completedAt: Date;
}

export enum QuietSpaceType {
  BREATHING = 'breathing',
  GROUNDING = 'grounding',
  RELAXATION = 'relaxation',
  REFLECTION = 'reflection'
}

export interface ResourceCompletion {
  resourceId: string;
  completedAt: Date;
  timeSpent: number;
}

export interface ChallengeCompletion {
  challengeId: string;
  completedAt: Date;
}

export interface PersonalActivity {
  id: string;
  type: string;
  description: string;
  duration: number;
  createdAt: Date;
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
}

export interface LoginCredentials {
  email: string;
  password: string;
  rememberMe?: boolean;
}

export interface RegisterData {
  email: string;
  password: string;
  confirmPassword: string;
  firstName: string;
  lastName: string;
  role: UserRole;
  campus: Campus;
  studentId?: string;
  staffId?: string;
  program?: string;
  yearOfStudy?: number;
}

export interface SupportRequest {
  id: string;
  studentId: string;
  studentName: string;
  studentProgram: string;
  studentYear: number;
  studentAvatar?: string;
  counselorId: string;
  status: 'pending' | 'accepted' | 'completed' | 'escalated';
  category: string;
  urgency: 'Low' | 'Medium' | 'High';
  message: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface TrainingModule {
  id: string;
  title: string;
  description: string;
  icon: string;
  iconColor: string;
  required: boolean;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  duration: number;
  lessons: number;
  progress: number;
  category: string;
}

export interface Escalation {
  id: string;
  studentId: string;
  studentName: string;
  studentProgram: string;
  studentYear: number;
  peerCounselorId: string;
  peerCounselorName: string;
  status: 'pending' | 'assigned' | 'in_progress' | 'resolved';
  urgency: 'Low' | 'Medium' | 'High';
  reason: string;
  peerNotes?: string;
  createdAt: Date;
  updatedAt: Date;
  assignedCounsellorId?: string;
}

export interface Appointment {
  id: string;
  studentId: string;
  studentName: string;
  studentProgram: string;
  studentYear: number;
  studentAvatar?: string;
  counsellorId: string;
  date: Date;
  time: string;
  duration: number;
  type: 'initial' | 'followup' | 'crisis' | 'assessment';
  isVirtual: boolean;
  location?: string;
  status: 'pending' | 'confirmed' | 'cancelled' | 'completed';
  notes?: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface SupervisionSession {
  id: string;
  counsellorId: string;
  counselorId: string;
  counselorName: string;
  counselorAvatar?: string;
  date: Date;
  time: string;
  duration: number;
  focusAreas: string[];
  notes?: string;
  status: 'scheduled' | 'in_progress' | 'completed' | 'cancelled' | 'rescheduled';
  createdAt: Date;
  updatedAt?: Date;
}