import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { Campus, CampusInfo, CAMPUS_DATA, CAMPUS_LIST } from '../models/campus.model';

@Injectable({
  providedIn: 'root'
})
export class CampusService {
  private selectedCampusSubject = new BehaviorSubject<Campus>(Campus.RUARAKA);
  public selectedCampus$ = this.selectedCampusSubject.asObservable();

  constructor() {
    const stored = localStorage.getItem('kca_selected_campus');
    if (stored && Object.values(Campus).includes(stored as Campus)) {
      this.selectedCampusSubject.next(stored as Campus);
    }
  }

  getCampuses(): CampusInfo[] {
    return CAMPUS_LIST;
  }

  getCampusInfo(campus: Campus): CampusInfo {
    return CAMPUS_DATA[campus];
  }

  getSelectedCampus(): Campus {
    return this.selectedCampusSubject.value;
  }

  setSelectedCampus(campus: Campus): void {
    this.selectedCampusSubject.next(campus);
    localStorage.setItem('kca_selected_campus', campus);
  }

  getCampusById(id: string): CampusInfo | undefined {
    return CAMPUS_LIST.find(c => c.id === id);
  }

  getCampusName(campus: Campus): string {
    return CAMPUS_DATA[campus].name;
  }

  getCampusFullName(campus: Campus): string {
    return CAMPUS_DATA[campus].fullName;
  }
}

// Re-export types for convenience
export { Campus, CampusInfo } from '../models/campus.model';