import { Injectable } from '@angular/core';
import { CanActivate, Router, UrlTree } from '@angular/router';
import { Observable } from 'rxjs';
import { map, take } from 'rxjs/operators';
import { AuthService } from '../services/auth.service';
import { UserRole } from '../models/user.model';

@Injectable({
  providedIn: 'root'
})
export class AuthGuard implements CanActivate {
  constructor(
    private authService: AuthService,
    private router: Router
  ) {}

  canActivate(): Observable<boolean | UrlTree> {
    return this.authService.authState$.pipe(
      take(1),
      map(state => {
        if (state.isAuthenticated && state.user) {
          return true;
        }
        return this.router.createUrlTree(['/auth/login']);
      })
    );
  }
}

@Injectable({
  providedIn: 'root'
})
export class RoleGuard implements CanActivate {
  constructor(
    private authService: AuthService,
    private router: Router
  ) {}

  canActivate(route: any): Observable<boolean | UrlTree> {
    const allowedRoles = route.data?.roles as UserRole[];
    
    return this.authService.authState$.pipe(
      take(1),
      map(state => {
        if (!state.isAuthenticated || !state.user) {
          return this.router.createUrlTree(['/auth/login']);
        }
        
        if (allowedRoles && allowedRoles.length > 0) {
          if (!allowedRoles.includes(state.user.role)) {
            return this.redirectToDashboard(state.user.role);
          }
        }
        
        return true;
      })
    );
  }

  private redirectToDashboard(role: UserRole): UrlTree {
    switch (role) {
      case UserRole.STUDENT:
        return this.router.createUrlTree(['/student/dashboard']);
      case UserRole.PEER_COUNSELOR:
        return this.router.createUrlTree(['/peer-counselor/dashboard']);
      case UserRole.GUIDANCE_STAFF:
        return this.router.createUrlTree(['/guidance/dashboard']);
      case UserRole.ADMIN:
        return this.router.createUrlTree(['/admin/dashboard']);
      default:
        return this.router.createUrlTree(['/']);
    }
  }
}

