import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { delay } from 'rxjs/operators';
import { User, UserRole } from '../models/user.model';

export interface Message {
  id: string;
  conversationId: string;
  senderId: string;
  senderName: string;
  senderRole: UserRole;
  senderAvatar?: string;
  content: string;
  type: 'text' | 'image' | 'file' | 'system';
  timestamp: Date;
  read: boolean;
  delivered: boolean;
  attachments?: Attachment[];
}

export interface Attachment {
  id: string;
  name: string;
  url: string;
  type: string;
  size: number;
}

export interface Conversation {
  id: string;
  participantIds: string[];
  participantNames: Record<string, string>;
  participantAvatars: Record<string, string>;
  participantRoles: Record<string, UserRole>;
  lastMessage?: Message;
  unreadCount: number;
  updatedAt: Date;
  isGroup: boolean;
  groupName?: string;
  groupAvatar?: string;
}

export interface ChatState {
  conversations: Conversation[];
  activeConversationId: string | null;
  messages: Record<string, Message[]>;
  typingUsers: Record<string, string[]>;
  onlineUsers: Set<string>;
}

@Injectable({
  providedIn: 'root'
})
export class ChatService {
  private stateSubject = new BehaviorSubject<ChatState>({
    conversations: [],
    activeConversationId: null,
    messages: {},
    typingUsers: {},
    onlineUsers: new Set()
  });

  public state$ = this.stateSubject.asObservable();

  constructor() {
    this.loadMockData();
  }

  private loadMockData(): void {
    const mockConversations: Conversation[] = [
      {
        id: 'conv-1',
        participantIds: ['current-user', 'peer-1'],
        participantNames: { 'current-user': 'John Doe', 'peer-1': 'Jane Smith' },
        participantAvatars: { 'current-user': '', 'peer-1': 'assets/images/avatars/peer1.jpg' },
        participantRoles: { 'current-user': UserRole.STUDENT, 'peer-1': UserRole.PEER_COUNSELOR },
        lastMessage: {
          id: 'msg-1',
          conversationId: 'conv-1',
          senderId: 'peer-1',
          senderName: 'Jane Smith',
          senderRole: UserRole.PEER_COUNSELOR,
          content: 'Hi! How can I help you today?',
          type: 'text',
          timestamp: new Date(Date.now() - 300000),
          read: false,
          delivered: true
        },
        unreadCount: 1,
        updatedAt: new Date(Date.now() - 300000),
        isGroup: false
      },
      {
        id: 'conv-2',
        participantIds: ['current-user', 'guidance-1'],
        participantNames: { 'current-user': 'John Doe', 'guidance-1': 'Dr. James Mwangi' },
        participantAvatars: { 'current-user': '', 'guidance-1': 'assets/images/avatars/guidance1.jpg' },
        participantRoles: { 'current-user': UserRole.STUDENT, 'guidance-1': UserRole.GUIDANCE_STAFF },
        lastMessage: {
          id: 'msg-2',
          conversationId: 'conv-2',
          senderId: 'guidance-1',
          senderName: 'Dr. James Mwangi',
          senderRole: UserRole.GUIDANCE_STAFF,
          content: 'Your appointment is confirmed for tomorrow at 10 AM.',
          type: 'text',
          timestamp: new Date(Date.now() - 3600000),
          read: true,
          delivered: true
        },
        unreadCount: 0,
        updatedAt: new Date(Date.now() - 3600000),
        isGroup: false
      }
    ];

    const mockMessages: Record<string, Message[]> = {
      'conv-1': [
        {
          id: 'msg-1-1',
          conversationId: 'conv-1',
          senderId: 'current-user',
          senderName: 'John Doe',
          senderRole: UserRole.STUDENT,
          content: 'Hello, I\'m feeling a bit stressed about exams.',
          type: 'text',
          timestamp: new Date(Date.now() - 600000),
          read: true,
          delivered: true
        },
        {
          id: 'msg-1',
          conversationId: 'conv-1',
          senderId: 'peer-1',
          senderName: 'Jane Smith',
          senderRole: UserRole.PEER_COUNSELOR,
          content: 'Hi! How can I help you today?',
          type: 'text',
          timestamp: new Date(Date.now() - 300000),
          read: false,
          delivered: true
        }
      ],
      'conv-2': [
        {
          id: 'msg-2',
          conversationId: 'conv-2',
          senderId: 'guidance-1',
          senderName: 'Dr. James Mwangi',
          senderRole: UserRole.GUIDANCE_STAFF,
          content: 'Your appointment is confirmed for tomorrow at 10 AM.',
          type: 'text',
          timestamp: new Date(Date.now() - 3600000),
          read: true,
          delivered: true
        }
      ]
    };

    this.stateSubject.next({
      conversations: mockConversations,
      activeConversationId: null,
      messages: mockMessages,
      typingUsers: {},
      onlineUsers: new Set(['peer-1', 'guidance-1'])
    });
  }

  getConversations(): Observable<Conversation[]> {
    return of(this.stateSubject.value.conversations);
  }

  getConversation(id: string): Conversation | undefined {
    return this.stateSubject.value.conversations.find(c => c.id === id);
  }

  getMessages(conversationId: string): Message[] {
    return this.stateSubject.value.messages[conversationId] || [];
  }

  getActiveConversation(): Conversation | null {
    const state = this.stateSubject.value;
    if (!state.activeConversationId) return null;
    return this.getConversation(state.activeConversationId) || null;
  }

  setActiveConversation(conversationId: string | null): void {
    const state = this.stateSubject.value;
    if (conversationId) {
      const conversations = state.conversations.map(c => 
        c.id === conversationId ? { ...c, unreadCount: 0 } : c
      );
      
      const messages = state.messages[conversationId]?.map(m => 
        m.senderId !== 'current-user' ? { ...m, read: true } : m
      ) || [];
      
      this.stateSubject.next({
        ...state,
        conversations,
        activeConversationId: conversationId,
        messages: { ...state.messages, [conversationId]: messages }
      });
    } else {
      this.stateSubject.next({ ...state, activeConversationId: null });
    }
  }

  sendMessage(conversationId: string, content: string, type: Message['type'] = 'text'): Observable<Message> {
    const state = this.stateSubject.value;
    const currentUser = this.getCurrentUser();
    
    const newMessage: Message = {
      id: `msg-${Date.now()}`,
      conversationId,
      senderId: currentUser.id,
      senderName: `${currentUser.firstName} ${currentUser.lastName}`,
      senderRole: currentUser.role,
      senderAvatar: currentUser.avatarUrl,
      content,
      type,
      timestamp: new Date(),
      read: false,
      delivered: true
    };

    const conversations = state.conversations.map(c => 
      c.id === conversationId 
        ? { ...c, lastMessage: newMessage, updatedAt: new Date(), unreadCount: c.unreadCount + (c.participantIds.includes(currentUser.id) ? 0 : 1) }
        : c
    );

    const messages = {
      ...state.messages,
      [conversationId]: [...(state.messages[conversationId] || []), newMessage]
    };

    this.stateSubject.next({ ...state, conversations, messages });
    
    setTimeout(() => {
      this.updateMessageStatus(conversationId, newMessage.id, { delivered: true });
    }, 500);

    return of(newMessage).pipe(delay(100));
  }

  private updateMessageStatus(conversationId: string, messageId: string, updates: Partial<Message>): void {
    const state = this.stateSubject.value;
    const messages = state.messages[conversationId]?.map(m => 
      m.id === messageId ? { ...m, ...updates } : m
    ) || [];
    
    this.stateSubject.next({ ...state, messages: { ...state.messages, [conversationId]: messages } });
  }

  markAsRead(conversationId: string): void {
    const state = this.stateSubject.value;
    const messages = state.messages[conversationId]?.map(m => ({ ...m, read: true })) || [];
    const conversations = state.conversations.map(c => 
      c.id === conversationId ? { ...c, unreadCount: 0 } : c
    );
    
    this.stateSubject.next({ ...state, messages: { ...state.messages, [conversationId]: messages }, conversations });
  }

  startTyping(conversationId: string, userId: string): void {
    const state = this.stateSubject.value;
    const typing = state.typingUsers[conversationId] || [];
    if (!typing.includes(userId)) {
      this.stateSubject.next({
        ...state,
        typingUsers: { ...state.typingUsers, [conversationId]: [...typing, userId] }
      });
    }
  }

  stopTyping(conversationId: string, userId: string): void {
    const state = this.stateSubject.value;
    const typing = state.typingUsers[conversationId] || [];
    this.stateSubject.next({
      ...state,
      typingUsers: { ...state.typingUsers, [conversationId]: typing.filter(id => id !== userId) }
    });
  }

  getTypingUsers(conversationId: string): string[] {
    return this.stateSubject.value.typingUsers[conversationId] || [];
  }

  isUserOnline(userId: string): boolean {
    return this.stateSubject.value.onlineUsers.has(userId);
  }

  setUserOnline(userId: string, online: boolean): void {
    const state = this.stateSubject.value;
    const onlineUsers = new Set(state.onlineUsers);
    if (online) {
      onlineUsers.add(userId);
    } else {
      onlineUsers.delete(userId);
    }
    this.stateSubject.next({ ...state, onlineUsers });
  }

  createConversation(participantId: string): Observable<Conversation> {
    const state = this.stateSubject.value;
    const currentUser = this.getCurrentUser();
    const participant = this.getUserById(participantId);
    
    if (!participant) {
      throw new Error('Participant not found');
    }

    const newConversation: Conversation = {
      id: `conv-${Date.now()}`,
      participantIds: [currentUser.id, participantId],
      participantNames: { 
        [currentUser.id]: `${currentUser.firstName} ${currentUser.lastName}`, 
        [participantId]: `${participant.firstName} ${participant.lastName}` 
      },
      participantAvatars: { 
        [currentUser.id]: currentUser.avatarUrl || '', 
        [participantId]: participant.avatarUrl || '' 
      },
      participantRoles: { 
        [currentUser.id]: currentUser.role, 
        [participantId]: participant.role 
      },
      unreadCount: 0,
      updatedAt: new Date(),
      isGroup: false
    };

    const conversations = [newConversation, ...state.conversations];
    this.stateSubject.next({ ...state, conversations, messages: { ...state.messages, [newConversation.id]: [] } });
    
    return of(newConversation).pipe(delay(100));
  }

  escalateToSupervisor(conversationId: string, reason: string): Observable<void> {
    return of(void 0).pipe(delay(500));
  }

  requestSupervisorSupport(conversationId: string): Observable<void> {
    return of(void 0).pipe(delay(500));
  }

  reportConversation(conversationId: string, reason: string): Observable<void> {
    return of(void 0).pipe(delay(500));
  }

  getConversationsForCounselor(counselorId: string): any[] {
    const state = this.stateSubject.value;
    return state.conversations.filter(c => 
      c.participantIds.includes(counselorId) || c.participantRoles[counselorId] === UserRole.PEER_COUNSELOR
    ).map(c => {
      const otherId = c.participantIds.find(id => id !== counselorId);
      return {
        ...c,
        name: otherId ? c.participantNames[otherId] : '',
        avatar: otherId ? c.participantAvatars[otherId] : '',
        isOnline: otherId ? this.isUserOnline(otherId) : false,
        lastMessage: c.lastMessage?.content || '',
        lastMessageTime: c.lastMessage?.timestamp || c.updatedAt,
        messages: this.getMessages(c.id)
      };
    });
  }

  private getCurrentUser(): User {
    return {
      id: 'current-user',
      email: 'student@kca.ac.ke',
      firstName: 'John',
      lastName: 'Doe',
      role: UserRole.STUDENT,
      campus: 'ruaraka' as any,
      isActive: true,
      createdAt: new Date()
    };
  }

  private getUserById(userId: string): User | undefined {
    const users: Record<string, User> = {
      'peer-1': {
        id: 'peer-1',
        email: 'peer@kca.ac.ke',
        firstName: 'Jane',
        lastName: 'Smith',
        role: UserRole.PEER_COUNSELOR,
        campus: 'ruaraka' as any,
        isActive: true,
        createdAt: new Date(),
        avatarUrl: 'assets/images/avatars/peer1.jpg'
      },
      'guidance-1': {
        id: 'guidance-1',
        email: 'guidance@kca.ac.ke',
        firstName: 'Dr. James',
        lastName: 'Mwangi',
        role: UserRole.GUIDANCE_STAFF,
        campus: 'ruaraka' as any,
        isActive: true,
        createdAt: new Date(),
        avatarUrl: 'assets/images/avatars/guidance1.jpg'
      }
    };
    return users[userId];
  }
}