import { Component, Input, Output, EventEmitter, forwardRef, HostBinding } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

export type ButtonVariant = 'primary' | 'secondary' | 'accent' | 'outline' | 'outline-secondary' | 'ghost' | 'danger' | 'success';
export type ButtonSize = 'sm' | 'md' | 'lg' | 'icon';

@Component({
  selector: 'app-button',
  template: `
    <button
      [type]="type"
      [class]="buttonClasses"
      [disabled]="disabled || loading"
      (click)="onClick($event)"
      [attr.aria-label]="ariaLabel"
      [attr.aria-pressed]="toggle ? pressed : null"
      [attr.aria-expanded]="toggle ? expanded : null"
    >
      <span *ngIf="loading" class="loading-spinner" aria-hidden="true"></span>
      <ng-content *ngIf="!loading"></ng-content>
      <span *ngIf="loading && !showSpinnerOnly">{{ label }}</span>
    </button>
  `,
  styles: [`
    :host {
      display: inline-flex;
    }
  `],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => ButtonComponent),
      multi: true
    }
  ]
})
export class ButtonComponent implements ControlValueAccessor {
  @Input() variant: ButtonVariant = 'primary';
  @Input() size: ButtonSize = 'md';
  @Input() type: 'button' | 'submit' | 'reset' = 'button';
  @Input() disabled = false;
  @Input() loading = false;
  @Input() block = false;
  @Input() label = '';
  @Input() ariaLabel = '';
  @Input() showSpinnerOnly = false;
  @Input() toggle = false;
  @Input() pressed = false;
  @Input() expanded = false;
  @Input() icon = '';
  @Input() iconPosition: 'left' | 'right' = 'left';
  @Input() fullWidth = false;

  @Output() clicked = new EventEmitter<Event>();

  @HostBinding('class')
  get buttonClasses(): string {
    const classes = ['btn', `btn-${this.variant}`, `btn-${this.size}`];
    
    if (this.block || this.fullWidth) {
      classes.push('btn-block');
    }
    
    if (this.toggle) {
      classes.push('btn-toggle');
    }
    
    if (this.pressed) {
      classes.push('active');
    }
    
    return classes.join(' ');
  }

  onClick(event: Event): void {
    if (!this.disabled && !this.loading) {
      this.clicked.emit(event);
      this.onChange(event);
      this.onTouched();
    }
  }

  onChange = (value: any) => {};
  onTouched = () => {};
  writeValue(value: any): void {}
  registerOnChange(fn: any): void { this.onChange = fn; }
  registerOnTouched(fn: any): void { this.onTouched = fn; }
  setDisabledState(isDisabled: boolean): void { this.disabled = isDisabled; }
}